import { setTimeout as delay } from 'node:timers/promises';
import { openPinnedHttps, readPinnedBody, type PinnedHttpsPolicy, type PinnedHttpsResponse, type PinnedHttpsTransport } from '../adminPinnedHttps';
import { metadataLookupClientProduct, metadataLookupConfiguration, type MetadataLookupConfiguration } from '../../config/metadataLookup';
import { METADATA_LOOKUP_LIMITS, METADATA_LOOKUP_RETRY, MetadataLookupSourceError, type LookupGateMode, type MetadataLookupSource } from './lookupContract';
import type { MetadataLookupRateGate } from './lookupRateGate';
import type { LookupResponseCache } from './lookupResponseCache';
import { decodeLookupJson } from './lookupResponseShape';

/**
 * The one request path shared by every metadata source client: configuration, cache, the
 * deployment-wide gate, the pinned fetcher, complete validation and the in-call 503/429 retry.
 */
export type LookupClientDependencies = {
    gate: MetadataLookupRateGate;
    /** Always injected: production passes `pinnedHttpsTransport`, tests a fixture transport. */
    transport: PinnedHttpsTransport;
    cache?: LookupResponseCache;
    configuration?: () => MetadataLookupConfiguration;
    sleep?: (ms: number, signal: AbortSignal) => Promise<void>;
    now?: () => number;
};
export type LookupCallOptions = { mode: LookupGateMode; signal: AbortSignal };

export type LookupJsonRequest<T> = {
    source: MetadataLookupSource;
    url: URL;
    destination: PinnedHttpsPolicy['destination'];
    accept: string;
    contentTypes: readonly string[];
    maximumBytes: number;
    deadlineMs: number;
    rateLimitStatuses: readonly number[];
    emptyStatuses: readonly number[];
    emptyValue: T;
    parse: (json: unknown) => T;
};

/** Retry-After as delta-seconds or an HTTP-date, clamped to [1 s, 30 s]; anything else is null. */
export const parseRetryAfter = (value: unknown, now: number): number | null => {
    if (typeof value !== 'string' || value.length > 64) return null;
    const text = value.trim();
    let ms: number;
    if (/^\d{1,9}$/.test(text)) ms = Number(text) * 1000;
    else if (/^[A-Za-z]{3}, \d{2} [A-Za-z]{3} \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(text) && Number.isFinite(Date.parse(text))) ms = Date.parse(text) - now;
    else return null;
    return Math.min(METADATA_LOOKUP_RETRY.retryAfterMaximumMs, Math.max(METADATA_LOOKUP_RETRY.retryAfterMinimumMs, ms));
};

/** `type/subtype` must be allowlisted, with no parameter other than `charset=utf-8`. */
const acceptableContentType = (header: unknown, allowed: readonly string[]) => {
    if (typeof header !== 'string' || header.length > 200) return false;
    const [type, ...parameters] = header.split(';').map(part => part.trim().toLowerCase());
    if (!allowed.includes(type)) return false;
    return parameters.every(parameter => /^charset="?utf-8"?$/.test(parameter));
};

const defaultSleep = (ms: number, signal: AbortSignal) => delay(ms, undefined, { signal }).then(() => undefined);
/** Internal marker only; every pinned failure is mapped to a bounded source error below. */
const pinnedFailure = () => new Error('METADATA_LOOKUP_PINNED_FAILURE');

/**
 * Sends one validated GET, retrying 503/429-style answers in wait mode at most
 * `METADATA_LOOKUP_RETRY.attempts` times. Nothing is sent while lookup is not configured; a cache hit
 * sends nothing; only complete answers (including an empty 404 answer) are cached.
 */
export async function requestLookupJson<T>(request: LookupJsonRequest<T>, options: LookupCallOptions, dependencies: LookupClientDependencies): Promise<T> {
    const { source } = request;
    const fail = (failure: 'unavailable' | 'invalidResponse' | 'cancelled' | 'notConfigured', retryAfterMs: number | null = null) =>
        new MetadataLookupSourceError(source, failure, retryAfterMs);
    const configuration = (dependencies.configuration ?? metadataLookupConfiguration)();
    if (!configuration.available) throw fail('notConfigured');
    const cacheKey = `${source} ${request.url.href}`;
    const cached = dependencies.cache?.get(cacheKey);
    if (cached) return cached.value as T;
    const now = dependencies.now ?? Date.now;
    const sleep = dependencies.sleep ?? defaultSleep;
    const attempts = options.mode === 'busy' ? 1 : METADATA_LOOKUP_RETRY.attempts;
    const policy: PinnedHttpsPolicy = {
        destination: request.destination,
        // MusicBrainz asks for a contact, and Cover Art Archive is its artwork service; Apple gets the product token only.
        headers: { Accept: request.accept, 'User-Agent': source === 'itunes' ? metadataLookupClientProduct : configuration.userAgent },
        maximumRedirects: METADATA_LOOKUP_LIMITS.maximumRedirects,
        failure: pinnedFailure
    };
    for (let attempt = 0; attempt < attempts; attempt++) {
        if (options.signal.aborted) throw fail('cancelled');
        const lease = await dependencies.gate.acquire(source, options.mode, options.signal);
        let backoffMs: number | undefined;
        try {
            const deadline = AbortSignal.any([options.signal, AbortSignal.timeout(request.deadlineMs)]);
            let response: PinnedHttpsResponse;
            try { ({ response } = await openPinnedHttps(request.url, deadline, { ...policy, beforeSend: () => lease.sent() }, dependencies.transport)); }
            catch { throw fail(options.signal.aborted ? 'cancelled' : 'unavailable'); }
            if (response.statusCode === 200) {
                const encoding = response.headers['content-encoding'];
                if (!acceptableContentType(response.headers['content-type'], request.contentTypes) || (encoding !== undefined && encoding !== 'identity')) {
                    response.body.destroy(); throw fail('invalidResponse');
                }
                let body: Buffer;
                try { body = await readPinnedBody(response, deadline, request.maximumBytes, pinnedFailure); }
                catch { response.body.destroy(); throw fail(options.signal.aborted ? 'cancelled' : 'unavailable'); }
                let value: T;
                try { value = request.parse(decodeLookupJson(body)); }
                catch { throw fail('invalidResponse'); }
                dependencies.cache?.set(cacheKey, value, body.length);
                return value;
            }
            response.body.destroy();
            if (request.emptyStatuses.includes(response.statusCode)) {
                dependencies.cache?.set(cacheKey, request.emptyValue, 64);
                return request.emptyValue;
            }
            if (!request.rateLimitStatuses.includes(response.statusCode)) throw fail('unavailable');
            const schedule = METADATA_LOOKUP_RETRY.backoffMs;
            backoffMs = parseRetryAfter(response.headers['retry-after'], now()) ?? schedule[Math.min(attempt, schedule.length - 1)];
            if (attempt === attempts - 1) throw new MetadataLookupSourceError(source, 'rateLimited', backoffMs);
        } finally {
            await lease.release(backoffMs === undefined ? undefined : { backoffMs });
        }
        try { await sleep(backoffMs, options.signal); }
        catch { throw fail('cancelled'); }
    }
    throw fail('unavailable');
}
